"""Layer 15 MLP down_proj, component 3394: a weak, mostly negative "code assignment" detector.

What it does: it is most negative on the assignment operator " =" (or " :=") when it
binds a value to a variable in code. The strongest cases are declarations such as
"const x = ", "var x = ", "let x = ", "int x = " (or an assignment at the start of an
indented line): about -2.3 on average. Plain assignments to an identifier ("result = ")
are about -1.4. An "=" after something that is not a name (a digit, ")", "]", "+", ...),
as in a maths equation, is about -0.5. Comparison operators (==, !=, >=, <=, =>) are
slightly positive. Digits and newlines are slightly negative. Everything else sits near
the component's mean of about -0.05. The first token of each document is 0 and the
second is +0.5. The program counts tokens within the current document and needs no other state.

Honest scope: this captures only the sparse, large negative part of the activation (code
assignments). Most of its variance is a diffuse spread over all tokens that no short
token rule captures, so the variance explained is small (about 0.03 to 0.04).
"""

import re

READS = ()

NAME_BEFORE = re.compile(r"\s?[A-Za-z_]\w*")
DECLARATION_WORDS = {
    "const", "var", "let", "int", "String", "mut", "val", "final", "auto", "my",
    "char", "float", "double", "bool", "long", "byte", "Int", "str", "dim", "local",
}
COMPARISONS = {" ==", " !=", " >=", " <=", " ===", " =>"}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        k = 0  # first token of a document
    else:
        k = carry[1] + 1
    carry = (doc, k)

    if k == 0:
        return carry, 0.0
    if k == 1:
        return carry, 0.5

    tok = prefix.token_strings[-1]
    before = prefix.token_strings[-2]
    if tok in (" =", " :="):
        if NAME_BEFORE.fullmatch(before):
            word_before_name = prefix.token_strings[-3].strip()
            starts_line = word_before_name == "" or word_before_name in DECLARATION_WORDS
            value = -2.3 if starts_line else -1.4
        else:
            value = -0.5
        if tok == " :=":
            value -= 0.5
    elif tok in COMPARISONS:
        value = 0.2
    elif tok.isdigit():
        value = -0.14
    elif "\n" in tok:
        value = -0.12
    else:
        value = -0.05
    return carry, value

"""Activation of MLP unit 3419 of layer 15 (down_proj), predicted from the words around it.

What it responds to: the logical connectives of reasoning text. The unit is
positive on words that open a contrast or a reason ("since", "because",
"although", "but", "however", "wait", "unless", "despite", "hmm") and on the
word right after one of them, and it is negative on words that draw a
conclusion or sum up ("therefore", "hence", "thus", "consequently", "why",
"so", "indeed"). A comma that closes an opener such as "Wait," or "However,"
is also positive. Its activation is diffuse, so word lists explain only a few
percent of its variance; this program captures the main sign and size.
"""

READS = ()

REASON = {"since", "because", "although", "though", "but", "however", "wait",
          "despite", "unless", "hmm", "whereas", "actually"}
WEAK_REASON = {"which", "where", "while"}
CONCLUDE = {"therefore", "hence", "thus", "consequently", "accordingly", "why",
            "otherwise", "finally", "so", "indeed", "probably"}


def _word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = _word(prefix.token_strings[-2]) if same_doc else ""
    value = 0.0
    if word in REASON:
        value += 2.0
    elif word in WEAK_REASON:
        value += 0.5
    if word in CONCLUDE:
        value -= 1.0
    if prev in REASON:
        value += 1.0
        if word == ",":
            value += 1.0
    elif prev in CONCLUDE:
        value -= 0.5
    return carry, value

"""Change-of-state detector for layers.15.mlp.down_proj component 3420.

The component's activation is almost always near 0, and goes strongly negative in
text about changing something into something else: converting, transferring,
transitioning, moving, switching ("convert from octal", "transition from",
"moved the point from", "transfer to"). Its negative direction promotes words like
"transition", "switch", "migrate", "from" and "between" as the next token.

This program reproduces that with words:
  - a STRONG change verb (convert, transfer, transition, move, shift, switch, ...)
    gives about -4.4;
  - a weaker change verb (change, replace, rename, copy, increase, jump, ...)
    gives about -1.3;
  - a preposition "from / to / into / between / over / through / across / onto"
    that follows a change verb within the last WINDOW tokens of the same document
    gives about -2.1 ("transition from", "convert to");
  - right after a STRONG verb, "from", "between", "over" give about -7.4 and "of",
    "the" about -5.1 ("transition from", "switch of", "convert the").
Everything else predicts 0. It is stateless: each step reads only the recent tokens.

What it captures: the sign and the rough size of the big negative spikes on
change-of-state words. What it misses: most of the variance, which is small
activations spread over ordinary tokens, and the many change-related spikes the
word lists do not reach, so variance explained is only a few percent.
"""

READS = ()

STRONG = {
    "convert", "converts", "converted", "converting", "conversion",
    "transfer", "transfers", "transferred", "transferring",
    "transition", "transitions", "transitioning", "transit",
    "transform", "transformed", "transforming", "transformation",
    "translate", "translated", "translating", "translation",
    "migrate", "migrated", "migrating", "migration",
    "move", "moves", "moved", "moving", "mv",
    "shift", "shifts", "shifted", "shifting",
    "switch", "switched", "switching", "swap",
}
CHANGE = {
    "change", "changes", "changed", "changing", "replace", "replaced",
    "rename", "renamed", "copy", "copied", "turn", "increase", "decrease",
    "jump", "jumped", "leap", "traded", "promote", "promoted", "upgrade",
}
PREPS = {"from", "to", "into", "between", "over", "through", "across", "onto"}
NEXT_TO_STRONG = {"from": -7.4, "between": -7.4, "over": -7.4, "of": -5.1, "the": -5.1}
WINDOW = 4  # how many tokens back a change verb may sit before a preposition


def _word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids
    now = len(doc) - 1
    word = _word(prefix.token_strings[now])
    if now > 0 and doc[now - 1] == doc[now]:
        before = _word(prefix.token_strings[now - 1])
        if before in STRONG and word in NEXT_TO_STRONG:
            return carry, NEXT_TO_STRONG[word]
    if word in STRONG:
        return carry, -4.4
    if word in CHANGE:
        return carry, -1.3
    if word in PREPS:
        for i in range(max(0, now - WINDOW), now):
            if doc[i] == doc[now]:
                before = _word(prefix.token_strings[i])
                if before in STRONG or before in CHANGE:
                    return carry, -2.1
    return carry, 0.0

"""Time-expression detector for layers.15.mlp.down_proj component 3423.

This component is sparse: most tokens sit near zero, it spikes positive inside
time-span language ("the last 8 years", "ten consecutive", "ever", "年"), and it
dips negative on calendar names (months, weekdays, times of day). The program
reads only the text so far and scores each token with these rules:

* the token itself, from a short table of time-span words (SPAN_WORDS);
* a calendar name (CALENDAR_NAMES) gets -1.5;
* the last digit of a 4-digit year from 1900 to 2029 gets +6 when the year
  starts a line or sentence (after LINE_START), otherwise +2.5; years 2030+ get 0;
* the token right after a time-span word gets +1.

Over the held-out eval rows this explains about 6% of the activation variance
(r about 0.26). It does not model the large, context-dependent spikes well.
"""

READS = ()

SPAN_WORDS = {
    " consecutive": 6.0, " annual": 5.0, " ever": 5.0, "年": 5.5,
    " recent": 4.0, " previous": 3.0, " straight": 3.0, " ago": 2.8,
    " future": 2.7, " past": 2.5, " last": 2.5, " next": 2.5, " decades": 2.5,
    " year": 2.3, " years": 2.0, " seasons": 2.0, " never": 2.0,
    "月": 2.0, "日": 2.0, "回": 2.0, "次": 2.0, " again": 1.3, " first": 1.3,
}
CALENDAR_NAMES = {
    " January", " February", " March", " April", " May", " June", " July",
    " August", " September", " October", " November", " December",
    " Monday", " Tuesday", " Wednesday", " Thursday", " Friday", " Saturday",
    " Sunday", " weekend", " morning", " afternoon", " evening", " night",
    " am", " pm",
}
LINE_START = ("\n", "。", "：", ":", "<|endoftext|>", "|", " \n", ".\n")


def is_digit(s):
    return len(s) == 1 and s.isdigit()


def year_just_completed(s):
    """True if the newest token is the last digit of a 4-digit year 1900-2029."""
    if len(s) < 4 or not all(is_digit(x) for x in s[-4:]):
        return False
    if len(s) > 4 and is_digit(s[-5]):
        return False
    century = s[-4] + s[-3]
    if century == "19":
        return True
    return century == "20" and s[-2] in "012"


def step(carry, prefix, upstream):
    s = prefix.token_strings
    t = s[-1]
    value = SPAN_WORDS.get(t, 0.0)
    if t in CALENDAR_NAMES:
        value -= 1.5
    if year_just_completed(s):
        value += 6.0 if (len(s) < 5 or s[-5] in LINE_START) else 2.5
    same_doc = len(s) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    if same_doc and s[-2] in SPAN_WORDS:
        value += 1.0
    return carry, value

"""Exceeding-comparison detector for one MLP output direction (layers.15 down_proj, #3430).

The component's output direction promotes words such as "beyond", "exceed", "surpass",
"plenty" and "超过", so it is a feature for "this quantity or standard goes above another".
It is active on the word that makes an exceeding comparison:
  - "than" after a comparative: strongest after "more" ("more than 10", "is more than"),
    strong after "greater/higher/larger/bigger", weaker after "less/better";
  - "over", "above", "beyond", "past", "exceed(ed)", "surpass", "plenty", "ample":
    strong when they state an excess ("is beyond", "well over", "plenty"), zero when
    locative ("the above", "control over");
  - "least" in "at least";
  - a little on the number slot right after such a word ("over [2]0", "more than [1]0").
It is switched off by negation ("no more than", "nothing more than", "not more than") and by
"rather than" / "other than", which are not comparisons of excess.
"""

READS = ()

COMPARATIVES = {"greater", "higher", "larger", "bigger", "longer", "stronger", "faster", "older",
                "smaller", "lower", "fewer", "less", "better", "worse", "earlier", "later"}
EXCEED = {"beyond", "exceeds", "exceed", "exceeded", "exceeding", "surpass", "surpassed",
          "surpasses", "plenty", "ample", "amply", "excess", "超过", "超越", "超出", "高于"}
LOCATIVE_BEFORE = {"the", "a", "an", "control", "all", "this", "that", "its", "his", "her", "of",
                   "from", "it", "my", "our", "their"}
DEGREE_BEFORE = {"way", "well", "far", "much", "substantially", "significantly", "by", "even"}
NEGATORS = {"no", "not", "nothing", "any", "anything", "none", "never", "little"}
PREDICATES = {"is", "are", "was", "were", "be", "been", "has", "have", "had", "will"}
DEGREE_WORDS = {"many", "much", "times", "several", "far", "easily", "already", "only"}
SLOT_AFTER = {1: 1.5, 2: 1.1, 3: 0.9, 4: 0.4}


def word(prefix, back):
    """The lowercased word `back` tokens before the newest one, within its document."""
    i = len(prefix.token_ids) - 1 - back
    if i < 0 or prefix.document_ids[i] != prefix.document_ids[-1]:
        return ""
    return prefix.token_strings[i].strip().lower()


def step(carry, prefix, upstream):
    w = word(prefix, 0)
    p1, p2, p3 = word(prefix, 1), word(prefix, 2), word(prefix, 3)
    value = 0.0
    if w == "than":
        if p1 in ("rather", "other"):
            value = 0.0
        elif p1 == "more":
            negated = bool({p2, p3} & NEGATORS)
            value = 1.0 if negated else (15.0 if p2 in PREDICATES else 10.0)
        elif p1 in COMPARATIVES:
            value = 4.0
        else:
            value = 2.0
    elif w in EXCEED:
        value = 0.3 if p1 in LOCATIVE_BEFORE else (12.0 if p1 in DEGREE_BEFORE else 5.0)
    elif w in ("over", "above", "past"):
        value = 0.3 if p1 in LOCATIVE_BEFORE else (12.0 if p1 in DEGREE_BEFORE else 1.5)
    elif w == "least" and p1 == "at":
        value = 2.7
    elif w in DEGREE_WORDS:
        value = 1.0
    elif w == "" or w.isdigit():
        for back in range(1, 5):
            if word(prefix, back) in ("than", "over", "above", "beyond", "least", "plenty"):
                value = SLOT_AFTER[back]
                break
    return carry, value

"""Layer 15 MLP down-projection, component 3431.

A weak, mostly token-level feature. It is positive where the text is turning:
at paragraph and list breaks ('.\\n\\n', ':\\n\\n'), at discourse connectives
that open a new step or a contrast ('But', 'So', 'Wait', 'Alternatively',
'Therefore'), and at sentence ends. It is near zero or negative inside
ordinary words, spaces, digits and CJK text.

Predicted value = the mean activation of the token's class. This explains only
about 2% of the variance, since the activation is mostly context noise.
"""
import re
from collections.abc import Mapping

READS: tuple[str, ...] = ()

TRANSITIONS = frozenset({
    "but", "however", "so", "wait", "alternatively", "therefore", "thus",
    "perhaps", "maybe", "hence", "which", "such", "instead",
})
CJK = re.compile(r"[぀-ヿ一-鿿가-힯]")


def token_class(tok: str) -> str:
    word = tok.strip().lower()
    if word in TRANSITIONS:
        return "transition"
    if "\n\n" in tok:
        return "list_break" if ":" in tok else "paragraph_break"
    if word in (".", "!", "?", "。"):
        return "sentence_end"
    if word in (",", "，"):
        return "comma"
    if "\n" in tok:
        return "newline"
    if word == "":
        return "space"
    if CJK.search(word):
        return "cjk"
    if word.isdigit():
        return "digit"
    if re.fullmatch(r"[a-z]+", word):
        return "lower_word"
    return "other"


MEAN = {
    "list_break": 2.5, "paragraph_break": 0.6, "transition": 1.5,
    "sentence_end": 0.7, "comma": 0.4, "newline": 0.0, "space": 0.1,
    "cjk": 0.0, "digit": 0.1, "lower_word": 0.1, "other": 0.2,
}


def step(carry, prefix, upstream: Mapping):
    return carry, MEAN[token_class(prefix.token_strings[-1])]

"""Candidate 2: concept word classes, gated by the preceding word.

Fires on a few word classes. Positive: degree words (most, more, best), career verbs
(played, spent), possessives (his, their, its), clause openers (To, For, One), and
ordinal or key adjectives (first, last, main, only). Negative: discourse connectives
(However, Wait). A degree or possessive word right after a preposition (at most, in his)
is damped.
"""
from collections.abc import Mapping

READS: tuple[str, ...] = ()

DEGREE = {"most", "more", "best", "less", "better"}
CAREER_VERBS = {"played", "spent", "spend", "finished", "began", "received", "pursued"}
POSSESSIVES = {"his", "her", "their", "its", "my", "our", "your"}
CLAUSE_OPENERS = {"To", "For", "One", "Another", "In"}
KEY_ADJECTIVES = {"first", "last", "main", "only", "next", "second", "entire"}
CONNECTIVES = {"However", "But", "Wait", "Although", "Thus", "Therefore", "Now", "Hmm", "Yes", "Not"}
PREPOSITIONS = {"in", "at", "on", "from", "by", "with", "for", "of", "or", "than", "into", "through", "about"}

W = dict(degree=1.7, career=1.2, possessive=0.6, opener=1.1, key=0.6, connective=-0.4)


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip() if same_doc else ""
    after_prep = before.lower() in PREPOSITIONS
    if word.lower() in DEGREE:
        value = W["degree"] if not after_prep else 0.3
    elif word in CAREER_VERBS:
        value = W["career"]
    elif word.lower() in POSSESSIVES:
        value = W["possessive"] if not after_prep else 0.0
    elif word in CLAUSE_OPENERS:
        value = W["opener"]
    elif word.lower() in KEY_ADJECTIVES:
        value = W["key"]
    elif word in CONNECTIVES:
        value = W["connective"]
    else:
        value = 0.0
    return carry, float(value)
